import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CqGPl1zp.js";const n="/newx-doc/assets/%E6%96%B0%E5%BB%BA%E5%BA%94%E7%94%A8.ePPlN5Dy.png",o="/newx-doc/assets/%E6%96%B0%E5%BB%BAAPI%E5%AF%86%E9%92%A5.YMFjm1Fd.png",p="/newx-doc/assets/API%E5%AF%86%E9%92%A5.BmRtvKUY.png",s="/newx-doc/assets/%E6%A8%A1%E5%9E%8B%E9%85%8D%E7%BD%AE.8yuL6p5p.png",d="/newx-doc/assets/AI%E5%AF%B9%E8%AF%9D.CauvvcDV.png",u=JSON.parse('{"title":"Dify 工作流","description":"","frontmatter":{},"headers":[],"relativePath":"ai/dify.md","filePath":"ai/dify.md","lastUpdated":null}'),h={name:"ai/dify.md"};function l(f,a,c,g,_,A){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="dify-工作流" tabindex="-1">Dify 工作流 <a class="header-anchor" href="#dify-工作流" aria-label="Permalink to &quot;Dify 工作流&quot;">​</a></h1><h2 id="_1-dify-是什么" tabindex="-1">1. Dify 是什么？ <a class="header-anchor" href="#_1-dify-是什么" aria-label="Permalink to &quot;1. Dify 是什么？&quot;">​</a></h2><p>Dify 是一个开源的 LLM 应用开发平台。其直观的界面结合了 AI 工作流、RAG 管道、Agent、模型管理、可观测性功能等，让您可以快速从原型到生产。</p><p>它的官网是 <a href="https://dify.ai/" target="_blank" rel="noreferrer">https://dify.ai/</a>，可直接申请使用。</p><p>同时，它也是个开源项目，地址是 <a href="https://github.com/langgenius/dify" target="_blank" rel="noreferrer">https://github.com/langgenius/dify</a>，可以自行部署。</p><h2 id="_2-如何接入" tabindex="-1">2. 如何接入？ <a class="header-anchor" href="#_2-如何接入" aria-label="Permalink to &quot;2. 如何接入？&quot;">​</a></h2><p>由于 Dify 的 <a href="https://docs.dify.ai/zh-hans/guides/application-publishing/developing-with-apis" target="_blank" rel="noreferrer">对话接口</a> 不兼容 GPT 的接口，所以无法使用 <a href="./openai">《【模型接入】OpenAI》</a> 的方式，无法通过 OpenAIChatModel 进行接入。</p><p>不过，社区里有人提供了 <a href="https://github.com/fatwang2/dify2openai" target="_blank" rel="noreferrer">https://github.com/fatwang2/dify2openai</a> 项目，可以将 Dify 的对话接口转换为 OpenAI 的接口，这样就可以使用 OpenAIChatModel 进行接入了。</p><p>下面，我们讲解下，如何把我们系统中的 <a href="./chat">《AI 对话聊天》</a> ，接入到 Dify 的工作室（聊天助手、Agent、工作流等）。</p><h3 id="_2-1-第一步-创建-dify-应用" tabindex="-1">2.1 第一步：创建 Dify 应用 <a class="header-anchor" href="#_2-1-第一步-创建-dify-应用" aria-label="Permalink to &quot;2.1 第一步：创建 Dify 应用&quot;">​</a></h3><p>① 在 <a href="https://cloud.dify.ai/apps" target="_blank" rel="noreferrer">https://cloud.dify.ai/apps</a> 工作室，点击【创建空白应用】按钮，创建一个应用。具体怎么创建，可见 <a href="https://docs.dify.ai/zh-hans/guides/application-orchestrate/creating-an-application" target="_blank" rel="noreferrer">https://docs.dify.ai/zh-hans/guides/application-orchestrate/creating-an-application</a> 文档。</p><p><img src="'+n+'" alt="新建应用"></p><p>② 点击应用，切换到【访问 API】选项，再点击【API 密钥】按钮，之后点击【创建密钥】按钮，生成一个 API 密钥。</p><p><img src="'+o+'" alt="新建 API 密钥"></p><h3 id="_2-2-第二步-配置-api-密钥与模型" tabindex="-1">2.2 第二步：配置 API 密钥与模型 <a class="header-anchor" href="#_2-2-第二步-配置-api-密钥与模型" aria-label="Permalink to &quot;2.2 第二步：配置 API 密钥与模型&quot;">​</a></h3><p>〇 本地搭建 <a href="https://github.com/fatwang2/dify2openai" target="_blank" rel="noreferrer">https://github.com/fatwang2/dify2openai</a> 项目，将 Dify 的对话接口转换为 OpenAI 的接口。</p><p>① 在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，新建一个 Dify 的 API 密钥，填写上面的“密钥”，并设置 URL 为 <code>http://127.0.0.1:3000</code> 。如下图所示：</p><p><img src="'+p+'" alt="API 密钥"></p><p>② 在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，新建一个 Dify 的聊天模型，填写上面的“模型名称” + “API 密钥” + “API URL”。如下图所示：</p><p><img src="'+s+'" alt="模型配置"></p><h3 id="_2-3-第三步-ai-对话聊天" tabindex="-1">2.3 第三步：AI 对话聊天 <a class="header-anchor" href="#_2-3-第三步-ai-对话聊天" aria-label="Permalink to &quot;2.3 第三步：AI 对话聊天&quot;">​</a></h3><p>在 [AI 大模型 -&gt; AI 对话] 菜单，选择 Dify 的聊天模型，即可开始对话。如下图所示：</p><p><img src="'+d+'" alt="AI 对话"></p><h2 id="_3-常见问题" tabindex="-1">3. 常见问题？ <a class="header-anchor" href="#_3-常见问题" aria-label="Permalink to &quot;3. 常见问题？&quot;">​</a></h2><p>① 如果你想使用 Dify 知识库接口，可参考 <a href="https://docs.dify.ai/zh-hans/guides/knowledge-base/external-knowledge-api-documentation" target="_blank" rel="noreferrer">https://docs.dify.ai/zh-hans/guides/knowledge-base/external-knowledge-api-documentation</a> 进行对接。</p><p>当然，我们系统已经提供了 <a href="./knowledge">《AI 知识库》</a> 功能。</p><p>② 如果使用 Dify 对话接口时，需要传递 <code>input</code>、<code>files</code> 等参数，无法采用上述方式接入。</p><p>此时，只能参考 OpenAiChatModel 的源码，实现类似 DifyChatModel 的接入，甚至要修改 <code>dify2openai</code> 源码。</p>',28)])])}const m=e(h,[["render",l]]);export{u as __pageData,m as default};
